function hpssd1()
  if gg.choice({
    "哈普苏特神殿①",
  }, nil, "---请选择地图---") == 1 then
    qa()
  end
  GY = -1
  sddw()
end

function qa()
    L_x = -1.89061570168
    L_z = -1.68648116589
    L_y = -2.68863272667
  end

function sddw()
  gg.clearList()
  gg.setRanges(gg.REGION_C_ALLOC)
  gg.clearResults()
  gg.searchNumber("0.70710676908F;0.10000000149F;0.80000001192F;1.5F;1D;10D::29", gg.TYPE_FLOAT, false, gg.SIGN_EQUAL, 0, -1)
  gg.searchNumber("10", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
  jg = gg.getResults(100)
  sl = gg.getResultCount()
  if 100 < sl then
    sl = 100
  end
  for _FORV_3_ = 1, sl do
    dzy = jg[_FORV_3_].address
    gg.addListItems({
      [1] = {
        address = dzy + 24,
        flags = gg.TYPE_FLOAT,
        freeze = true,
        value = L_x
      }
    })
    gg.addListItems({
      [1] = {
        address = dzy + 32,
        flags = gg.TYPE_FLOAT,
        freeze = true,
        value = L_z
      }
    })
    gg.addListItems({
      [1] = {
        address = dzy + 40,
        flags = gg.TYPE_FLOAT,
        freeze = true,
        value = L_y
      }
    })
  end
  gg.toast("成功")
  gg.clearResults()
end



